attempts.query:
PREFIX : <https://w3id.org/rastro/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT (SUM(?sr) AS ?total) WHERE {
  {
    SELECT DISTINCT ?d WHERE {
      ?l rdfs:label "Lung Neoplasms"@en .
      ?c :within ?l .
      ?t a :Trial ; :condition ?c ; :status ?st ; :testsDrug ?d .
      FILTER(?st IN ("RECRUITING", "ACTIVE_NOT_RECRUITING", "NOT_YET_RECRUITING", "ENROLLING_BY_INVITATION"))
      ?d :hasTarget ?tg . ?tg :gene "EGFR" .
    }
  }
  ?y a :YearlyReports ; :drug ?d ; :seriousReports ?sr .
}
